-- STORED PROCEDURES


-- Create stored procedure
CREATE PROCEDURE MQTT.sp_GetReceiversByBroker
    @BrokerID INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        ReceiverConfigID,
        Topic,
        QoS,
        IsEnabled,
        CreatedDate
    FROM MQTT.ReceiverConfig
    WHERE BrokerID = @BrokerID
    ORDER BY Topic
END

